using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Threading.Tasks;using System.Windows;using System.Windows.Controls;using System.Windows.Input;using System.Windows.Media;using System.Windows.Interop;using System.Runtime.InteropServices;using System.Windows.Automation;using Gunt.ControlCenter.Services;using Gunt.ControlCenter.Models;
namespace Gunt.ControlCenter.Views {
 public sealed class DeveloperPopup:Window {
  readonly System.Diagnostics.Stopwatch creation=System.Diagnostics.Stopwatch.StartNew();
  readonly DesktopService service;readonly string root;readonly Action<string> navigate;readonly TextBlock feedback=new TextBlock{TextWrapping=TextWrapping.Wrap};readonly StackPanel panel=new StackPanel{Margin=new Thickness(16)};readonly Brush surface=UxTheme.Background,text=UxTheme.Text,muted=UxTheme.Muted;bool busy,ready,closing,returnFocus;Panel feedbackHost;ProjectEntry snapshotProject;readonly IInputElement previousFocus=Keyboard.FocusedElement;
  public DeveloperPopup(string directory,bool palette,Action<string> navigate=null){root=directory;service=new DesktopService(root);this.navigate=navigate;Title=palette?"GUnT_0x9 명령 팔레트":"GUnT_0x9 빠른 패널";Width=palette?680:360;Height=palette?460:Double.NaN;SizeToContent=palette?SizeToContent.Manual:SizeToContent.Height;MaxHeight=650;MinWidth=320;MinHeight=palette?350:0;Background=surface;Foreground=text;FontFamily=new FontFamily("S-Core Dream 4 Regular, Manrope, Malgun Gothic, Segoe UI");FontSize=13;UseLayoutRounding=true;SnapsToDevicePixels=true;ShowInTaskbar=false;Topmost=true;WindowStyle=WindowStyle.ToolWindow;ResizeMode=ResizeMode.NoResize;WindowStartupLocation=WindowStartupLocation.CenterScreen;Resources.MergedDictionaries.Add(UxTheme.Resources);Content=new ScrollViewer{Content=panel,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};if(palette)BuildPalette();else BuildPanel();feedback.Foreground=muted;(feedbackHost??panel).Children.Add(feedback);PreviewKeyDown+=delegate(object s,KeyEventArgs e){if(e.Key==Key.Escape&&!busy){returnFocus=true;Close();e.Handled=true;}};SourceInitialized+=delegate{int dark=1;DwmSetWindowAttribute(new WindowInteropHelper(this).Handle,20,ref dark,4);};Loaded+=delegate{Position(palette);ready=true;};ContentRendered+=delegate{if(creation.IsRunning){creation.Stop();Gunt.ControlCenter.Infrastructure.UiPerformance.Record(root,palette?"palette-first-render":"panel-first-render",creation.Elapsed.TotalMilliseconds);}};Closing+=delegate(object sender,System.ComponentModel.CancelEventArgs e){if(busy){e.Cancel=true;feedback.Text="실행 요청 처리 중입니다. 완료 후 닫으세요.";}else{closing=true;if(palette)returnFocus=true;}};Closed+=delegate{if(returnFocus&&Owner!=null&&Owner.IsVisible){Owner.Activate();if(previousFocus!=null)Keyboard.Focus(previousFocus);}};Deactivated+=delegate{if(!palette&&ready&&!busy&&!closing&&!IsOwnedDialogOpen())Close();};}
  bool IsOwnedDialogOpen(){return OwnedWindows.Count>0;}
  void Position(bool palette){var point=System.Windows.Forms.Cursor.Position;var screen=System.Windows.Forms.Screen.FromPoint(point);var work=screen.WorkingArea;double scale=GuntLayout.Scale(screen);var h=new WindowInteropHelper(this).Handle;int width=(int)Math.Min(Width*scale,work.Width-16),height=(int)Math.Min(ActualHeight*scale,work.Height-16);MinWidth=Math.Min(MinWidth,width/scale);MinHeight=Math.Min(MinHeight,height/scale);int x=palette?work.Left+(work.Width-width)/2:Math.Max(work.Left+8,Math.Min(point.X,work.Right-width-8));int y=palette?work.Top+(work.Height-height)/3:work.Top+8;SetWindowPos(h,IntPtr.Zero,x,y,width,height,0x14);}
  [DllImport("dwmapi.dll")]static extern int DwmSetWindowAttribute(IntPtr h,int attribute,ref int value,int size);
  [DllImport("user32.dll")]static extern bool SetWindowPos(IntPtr h,IntPtr a,int x,int y,int w,int z,uint flags);
  void Label(string value,bool secondary=false){panel.Children.Add(new TextBlock{Text=value,Foreground=secondary?muted:text,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,0,0,10)});}
  Button Button(Panel p,string title,Action action){var b=new Button{Content=title};AutomationProperties.SetName(b,title);b.Click+=delegate{try{action();}catch(Exception e){feedback.Text="처리 실패: "+e.Message;}};p.Children.Add(b);return b;}
  void Page(string id){if(navigate!=null)navigate(id);else service.OpenControlCenter(id);Close();}
  IEnumerable<Button> PopupButtons(DependencyObject parent){for(int i=0;i<VisualTreeHelper.GetChildrenCount(parent);i++){var child=VisualTreeHelper.GetChild(parent,i);var button=child as Button;if(button!=null)yield return button;foreach(var nested in PopupButtons(child))yield return nested;}}
  void Run(Func<string> action){if(busy)return;busy=true;var buttons=PopupButtons(panel).Where(b=>b.IsEnabled).ToArray();foreach(var button in buttons)button.IsEnabled=false;feedback.Text="처리 중…";Task.Factory.StartNew(action).ContinueWith(t=>Dispatcher.BeginInvoke((Action)delegate{busy=false;foreach(var button in buttons)button.IsEnabled=true;feedback.Text=t.IsFaulted?"실행 실패: "+t.Exception.GetBaseException().Message:t.Result;}));}
  void BuildPanel(){
   Label("현재 프로젝트",true);ProjectEntry project=null;
   try{project=service.ActiveProject();snapshotProject=project;Label(project.Name);panel.Children.Add(new TextBlock{Text=project.Directory,ToolTip=project.Directory,Foreground=muted,TextTrimming=TextTrimming.CharacterEllipsis,Margin=new Thickness(0,0,0,12)});}catch(Exception e){Label(e.Message,true);}
   var primary=new WrapPanel();panel.Children.Add(primary);var secondary=new WrapPanel();panel.Children.Add(secondary);
   DeveloperPreferences preferences=project==null?null:service.Preferences(project);
   foreach(var tool in new[]{new[]{"Codex","codex"},new[]{"OpenCode","opencode"},new[]{"VS Code","ide"},new[]{"폴더","folder"}}){
    string kind=tool[1];var launch=Button(kind=="folder"?secondary:primary,tool[0],()=>Run(()=>{var current=service.ActiveProject();if(project==null||current.Id!=project.Id||current.Directory!=project.Directory)throw new InvalidOperationException("프로젝트가 변경됐습니다. 빠른 패널을 다시 열어 확인하세요.");return service.LaunchDeveloper(current,kind);}));
    launch.IsEnabled=project!=null&&((kind!="codex"&&kind!="opencode")||!String.IsNullOrEmpty(preferences.WslDistribution));if(!launch.IsEnabled){launch.ToolTip=project==null?"프로젝트를 먼저 선택하세요.":"WSL 환경을 먼저 지정하세요.";ToolTipService.SetShowOnDisabled(launch,true);}
   }
   Button(secondary,"개발 세션 시작",StartSessionQuick).IsEnabled=project!=null;Button(secondary,"프로젝트 선택",()=>Page("developer-setup"));
   panel.Children.Add(new System.Windows.Shapes.Rectangle{Height=1,Fill=UxTheme.Border,Margin=new Thickness(0,4,0,12)});
   string profile=service.ProfileState();panel.Children.Add(new TextBlock{Text="작업공간 · "+profile.Split('(')[0].Trim(),ToolTip=profile,Foreground=muted,TextTrimming=TextTrimming.CharacterEllipsis,Margin=new Thickness(0,0,0,12)});
   var desktop=new WrapPanel();panel.Children.Add(desktop);Button(desktop,"모니터 표시 / 숨김",()=>Run(()=>{service.Action("monitor-toggle");return "모니터 전환 요청을 전달했습니다.";}));Button(desktop,"배경 재생 / 정지",()=>Run(()=>{service.Action("wallpaper-toggle");return "배경 재생 전환 요청을 전달했습니다.";}));Button(desktop,"프로필",()=>Page("profiles"));Button(desktop,"제어 센터",()=>Page("overview"));Button(desktop,"명령 팔레트",()=>{service.OpenControlCenter("palette");Close();});
  }
  void StartSessionQuick(){try{var p=service.ActiveProject();if(snapshotProject==null||snapshotProject.Id!=p.Id||snapshotProject.Directory!=p.Directory)throw new InvalidOperationException("프로젝트가 변경됐습니다. 패널을 다시 열어 확인하세요.");var prefs=service.Preferences(p);var preset=service.Sessions().Presets.FirstOrDefault(x=>x.Id==prefs.SessionPreset);if(preset==null)throw new ArgumentException("기본 개발 세션을 개발 설정에서 선택하세요.");busy=true;bool yes;try{yes=UxTheme.Confirm(this,"개발 세션 시작",service.SessionPreview(p,preset),"세션 시작 요청","취소")==0;}finally{busy=false;}if(!yes)return;bool command=false;if(preset.Actions.Any(x=>x.Enabled&&x.Kind=="command")){busy=true;try{command=UxTheme.Confirm(this,"프로젝트 명령 실행 허용",String.Join("\n",p.Commands??new List<string>()),"명령 실행 허용","취소")==0;}finally{busy=false;}}Run(()=>{var run=service.StartSession(p,preset,command);return run.Result+"\n"+String.Join("\n",run.Actions.Select(x=>x.ToString()));});}catch(Exception e){feedback.Text=e.Message;}}
  void BuildPalette(){
   var layout=new DockPanel{Margin=new Thickness(16)};Content=layout;
   var query=new TextBox{Tag="명령·프로젝트 검색",Margin=new Thickness(0,0,0,8)};AutomationProperties.SetName(query,"GUNT 명령 검색");DockPanel.SetDock(query,Dock.Top);layout.Children.Add(query);
   var footer=new StackPanel{Margin=new Thickness(0,8,0,0)};feedbackHost=footer;DockPanel.SetDock(footer,Dock.Bottom);layout.Children.Add(footer);
   var context=new TextBlock{Foreground=muted,TextTrimming=TextTrimming.CharacterEllipsis,Margin=new Thickness(0,0,0,8)};footer.Children.Add(context);
   var actions=new WrapPanel();footer.Children.Add(actions);
   var hint=new TextBlock{Text="↑ ↓ 선택    Enter 실행    Esc 닫기",Foreground=muted,FontSize=12};footer.Children.Add(hint);
   var results=new Grid();layout.Children.Add(results);var list=new ListBox();AutomationProperties.SetName(list,"GUNT 명령 결과");VirtualizingStackPanel.SetIsVirtualizing(list,true);VirtualizingStackPanel.SetVirtualizationMode(list,VirtualizationMode.Recycling);results.Children.Add(list);
   var empty=new TextBlock{Text="검색 결과가 없습니다. 명령이나 프로젝트 이름을 입력하세요.",Foreground=muted,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(8),Visibility=Visibility.Collapsed};results.Children.Add(empty);
   CommandEntry[] commands=service.Commands();CommandStore commandConfig=service.CommandsConfig();var projects=service.Projects();ProjectEntry active=null;try{active=service.ActiveProject();}catch{}snapshotProject=active;
   var preferences=projects.ToDictionary(p=>p.Id,p=>service.Preferences(p));
   var style=new Style(typeof(ListBoxItem),(Style)UxTheme.Resources[typeof(ListBoxItem)]);style.Setters.Add(new Setter(Control.PaddingProperty,new Thickness(8,4,8,4)));list.ItemContainerStyle=style;
   var row=new FrameworkElementFactory(typeof(StackPanel));var name=new FrameworkElementFactory(typeof(TextBlock));name.SetBinding(TextBlock.TextProperty,new System.Windows.Data.Binding());name.SetValue(TextBlock.TextTrimmingProperty,TextTrimming.CharacterEllipsis);row.AppendChild(name);
   var destination=new FrameworkElementFactory(typeof(TextBlock));destination.SetValue(TextBlock.FontSizeProperty,11.0);destination.SetValue(TextBlock.ForegroundProperty,muted);destination.SetValue(TextBlock.TextTrimmingProperty,TextTrimming.CharacterEllipsis);destination.SetBinding(TextBlock.TextProperty,new System.Windows.Data.Binding{Converter=new CommandDestination(projects,active)});row.AppendChild(destination);list.ItemTemplate=new DataTemplate{VisualTree=row};
   bool updating=false;Button executeButton=null,favoriteButton=null;
   Action preview=()=>{var entry=list.SelectedItem as CommandEntry;if(entry==null){context.Text="검색어를 바꾸어 다시 찾으세요.";}else{var project=String.IsNullOrEmpty(entry.ProjectId)?active:projects.FirstOrDefault(p=>p.Id==entry.ProjectId);if(entry.Action=="developer"||entry.Action=="session"){DeveloperPreferences prefs=null;if(project!=null)preferences.TryGetValue(project.Id,out prefs);context.Text=project==null?"선택된 프로젝트 없음 · 개발 세팅에서 선택하세요.":project.Name+" · "+(prefs==null||String.IsNullOrEmpty(prefs.WslDistribution)?"WSL 미지정":prefs.WslDistribution)+"\n"+project.Directory;}else context.Text=entry.Action=="page"?"설정 화면으로 이동":entry.Action=="profile"?"작업공간 변경 미리보기":"데스크톱 작업";}context.ToolTip=context.Text;if(executeButton!=null){executeButton.IsEnabled=entry!=null;favoriteButton.IsEnabled=entry!=null;}};
   list.SelectionChanged+=delegate{if(!updating)preview();};
   string lastQuery=null;Action filter=()=>{if(lastQuery==query.Text)return;var timing=System.Diagnostics.Stopwatch.StartNew();try{updating=true;var found=service.SearchCommands(query.Text,commands,commandConfig);list.ItemsSource=found;list.SelectedIndex=found.Length>0?0:-1;lastQuery=query.Text;empty.Visibility=found.Length==0?Visibility.Visible:Visibility.Collapsed;}catch(Exception e){feedback.Text=e.Message;}finally{updating=false;preview();Gunt.ControlCenter.Infrastructure.UiPerformance.Record(root,"palette-search",timing.Elapsed.TotalMilliseconds);}};
   Action execute=()=>{try{if(busy){feedback.Text="현재 실행 요청을 처리 중입니다.";return;}var command=list.SelectedItem as CommandEntry;if(command==null)return;if(command.Action=="page"){service.RememberCommand(command.Id);Page(command.Value);}else if(command.Action=="session"){StartSessionQuick();}else if(command.Action=="panel"){service.OpenControlCenter("quick-panel");Close();}else{if(command.Action=="developer"){var shown=String.IsNullOrEmpty(command.ProjectId)?active:projects.FirstOrDefault(p=>p.Id==command.ProjectId);var current=String.IsNullOrEmpty(command.ProjectId)?service.ActiveProject():service.Projects().FirstOrDefault(p=>p.Id==command.ProjectId);if(shown==null||current==null||shown.Id!=current.Id||shown.Directory!=current.Directory)throw new InvalidOperationException("프로젝트 대상이 변경됐습니다. 팔레트를 다시 열어 확인하세요.");}Run(()=>service.ExecuteCommand(command));}}catch(Exception e){feedback.Text=e.Message;}};
   executeButton=Button(actions,"선택 명령 실행",execute);favoriteButton=Button(actions,"즐겨찾기 전환",()=>{var selected=list.SelectedItem as CommandEntry;if(selected==null)return;service.FavoriteCommand(selected.Id);commands=service.Commands();commandConfig=service.CommandsConfig();lastQuery=null;filter();});
   query.TextChanged+=delegate{filter();};PreviewKeyDown+=delegate(object sender,KeyEventArgs args){if(!query.IsKeyboardFocusWithin&&!list.IsKeyboardFocusWithin)return;if(args.Key==Key.Down||args.Key==Key.Up){if(list.Items.Count>0){list.SelectedIndex=Math.Max(0,Math.Min(list.Items.Count-1,list.SelectedIndex+(args.Key==Key.Down?1:-1)));list.ScrollIntoView(list.SelectedItem);}args.Handled=true;}else if(args.Key==Key.Enter){execute();args.Handled=true;}};list.MouseDoubleClick+=delegate{execute();};filter();Loaded+=delegate{query.Focus();};
  }
  sealed class CommandDestination:System.Windows.Data.IValueConverter{
   readonly Dictionary<string,ProjectEntry> projects;readonly ProjectEntry active;
   public CommandDestination(ProjectEntry[] entries,ProjectEntry current){projects=entries.ToDictionary(project=>project.Id);active=current;}
   public object Convert(object value,Type target,object parameter,System.Globalization.CultureInfo culture){var command=value as CommandEntry;if(command==null)return "";ProjectEntry project=active;if(!String.IsNullOrEmpty(command.ProjectId))projects.TryGetValue(command.ProjectId,out project);if(command.Action=="developer"||command.Action=="session")return "개발 · "+(project==null?"프로젝트 선택 필요":project.Name);return command.Action=="page"?"설정":command.Action=="profile"?"작업공간":"데스크톱";}
   public object ConvertBack(object value,Type target,object parameter,System.Globalization.CultureInfo culture){throw new NotSupportedException();}
  }
 }
